320	func maybeInjectMemoryLoop(ctx context.Context, ag agent.Agent, event *agent.Event) error {
321		if event.Prompt == "" {
322			return nil
323		}
324	
325		writer, ok := agent.AsHookResponseWriter(ag)
326		if !ok {
327			return nil
328		}
329	
330		state, loadErr := memoryloop.LoadState(ctx)
331		if loadErr != nil {
332			state = &memoryloop.State{}
333		}
334		settingsValue, settingsErr := LoadEntireSettings(ctx)
335		if settingsErr != nil {
336			settingsValue = nil
337		}
338		mode := effectiveMemoryLoopMode(state, settingsValue)
339		debug := effectiveMemoryLoopDebug(state, settingsValue)
340		if state.Snapshot == nil {
341			return nil
342		}
343	
344		now := time.Now().UTC()
345		selectOpts := buildMemoryLoopSelectOpts(ctx, state.Snapshot)
346		report := memoryloop.PreviewSelection(*state.Snapshot, event.Prompt, now, selectOpts...)
347		if len(report.Matches) == 0 {
348			if debug {
349				if err := writer.WriteHookResponse(buildMemoryLoopDebugPrompt(event.Prompt, report)); err != nil {
350					return fmt.Errorf("failed to write memory-loop debug prompt: %w", err)
351				}
352			}
353			return nil
354		}
355		matches := report.Matches
356	
357		switch mode {
358		case memoryloop.ModeManual:
359			if !supportsManualMemoryPrompt(ag.Name()) {
360				return nil
361			}
362			if err := writer.WriteHookResponse(buildManualMemoryPrompt(matches)); err != nil {
363				return fmt.Errorf("failed to write manual memory prompt: %w", err)
364			}
365			return nil
366		case memoryloop.ModeAuto:
367			if !supportsAutoMemoryInjection(ag.Name()) || !state.Snapshot.InjectionEnabled {
368				return nil
369			}
370		default:
371			return nil
372		}
373	
374		message := memoryloop.FormatInjectionBlock(matches)
375		if strings.TrimSpace(event.ResponseMessage) != "" {
376			message = strings.TrimSpace(event.ResponseMessage) + "\n\n" + message
377		}
378		if contextWriter, ok := agent.AsHookContextWriter(ag); ok {
379			if err := contextWriter.WriteHookResponseWithContext(message, message); err != nil {
380				return fmt.Errorf("failed to write memory-loop hook response with context: %w", err)
381			}
382		} else {
383			if err := writer.WriteHookResponse(message); err != nil {
384				return fmt.Errorf("failed to write memory-loop hook response: %w", err)
385			}
386		}
387	
388		ids := make([]string, 0, len(matches))
389		reasons := make([]string, 0, len(matches))
390		for _, match := range matches {
391			ids = append(ids, match.Record.ID)
392			if match.Reason != "" {
393				reasons = append(reasons, match.Reason)
394			}
395		}
396	
397		logEntry := memoryloop.InjectionLog{
398			SessionID:         event.SessionID,
399			PromptPreview:     truncatePromptPreview(event.Prompt, 500),
400			InjectedMemoryIDs: ids,
401			InjectedAt:        now,
402			Reason:            strings.Join(reasons, ", "),
403		}
404		memoryloop.RecordInjectionActivity(state, matches, logEntry, now)
405		if err := memoryloop.SaveState(ctx, state); err != nil {
406			logging.Warn(logging.WithComponent(ctx, "lifecycle"), "failed to persist memory-loop injection activity",
407				slog.String("error", err.Error()))
408		}
409	
410		return nil
411	}
