431	func buildManualMemoryPrompt(matches []memoryloop.Match) string {
432		block := memoryloop.FormatInjectionBlock(matches)
433		if block == "" {
434			return ""
435		}
436		return block + "\n\n" +
437			"A relevant memory matches this prompt. Before doing substantive work, ask the user " +
438			"whether you should use this guidance for the task, and wait for their answer before continuing."
439	}

